274	/// Tool list for a server with or without data and memory. Used by `wrap`
275	/// (to estimate schema cost) and the function-calling exports.
276	pub fn tool_definitions(store: Option<&Store>, memory: Option<(MemoryTools, &str)>, data: bool) -> Value {
277	    let mut tools = if data { data_tools(store) } else { Vec::new() };
278	    if let Some((which, ns)) = memory {
279	        tools.extend(memory_tools(which, ns, data));
280	    }
281	    Value::Array(tools)
282	}
