284	/// Tool state for one client connection.
285	pub struct Session {
286	    opts: ServerOptions,
287	    store: Option<Store>,
288	    memory: Option<Memory>,
289	}
290	
291	fn text_arg(args: &Value, k: &str) -> Option<String> {
292	    args.get(k).and_then(Value::as_str).map(str::trim).filter(|s| !s.is_empty()).map(str::to_string)
293	}
294	
295	fn int_arg(args: &Value, k: &str) -> Option<usize> {
296	    args.get(k)
297	        .and_then(|v| v.as_u64().or_else(|| v.as_str().and_then(|s| s.trim().parse().ok())))
298	        .map(|v| v as usize)
299	}
300	
301	fn bool_arg(args: &Value, k: &str) -> bool {
302	    match args.get(k) {
303	        Some(Value::Bool(b)) => *b,
304	        Some(Value::String(s)) => matches!(s.trim(), "true" | "1" | "yes"),
305	        _ => false,
306	    }
307	}
308	
309	/// `where` (an object of field to value or values) and `where_list`
310	/// (`field=value` strings) as filter pairs.
311	fn where_filters(args: &Value) -> Result<Vec<(String, String)>> {
312	    let mut filters = Vec::new();
313	    if let Some(Value::Object(map)) = args.get("where") {
314	        for (field, v) in map {
315	            match v {
316	                Value::Array(items) => {
317	                    filters.extend(items.iter().filter_map(scalar).map(|s| (field.clone(), s)))
318	                }
319	                other => filters.extend(scalar(other).map(|s| (field.clone(), s))),
320	            }
321	        }
322	    }
323	    for f in list_arg(args, "where_list") {
324	        match f.split_once('=') {
325	            Some((k, v)) if !k.trim().is_empty() => filters.push((k.trim().into(), v.trim().into())),
326	            _ => bail!("where_list items look like field=value, got {f:?}"),
327	        }
328	    }
329	    Ok(filters)
330	}
331	
332	/// An array of strings, or one comma-separated string.
333	fn list_arg(args: &Value, k: &str) -> Vec<String> {
334	    match args.get(k) {
335	        Some(Value::Array(items)) => {
336	            items.iter().filter_map(scalar).filter(|s| !s.trim().is_empty()).collect()
337	        }
338	        Some(Value::String(s)) => {
339	            s.split(',').map(str::trim).filter(|s| !s.is_empty()).map(str::to_string).collect()
340	        }
341	        _ => Vec::new(),
342	    }
343	}
344	
345	fn kinds_arg(args: &Value) -> Result<Vec<Kind>> {
346	    list_arg(args, "kind")
347	        .iter()
348	        .map(|k| Kind::parse(k).ok_or_else(|| anyhow::anyhow!("unknown kind {k:?}; use {}", Kind::NAMES)))
349	        .collect()
350	}
351	
352	impl Session {
353	    pub fn new(opts: ServerOptions) -> Self {
354	        Self { opts, store: None, memory: None }
355	    }
356	
357	    /// Data tools are offered unless this is a memory server without an index.
358	    pub fn data_enabled(&self) -> bool {
359	        self.opts.memory.is_none() || self.opts.index.exists()
360	    }
361	
362	    pub fn memory_tools(&self) -> Option<MemoryTools> {
363	        self.opts.memory.as_ref().map(|m| m.tools)
364	    }
365	
366	    fn ensure_store(&mut self) -> Result<()> {
367	        match &mut self.store {
368	            Some(store) => {
369	                store.reload_if_replaced()?;
370	            }
371	            None => self.store = Some(Store::open(&self.opts.index, self.opts.card)?),
372	        }
373	        Ok(())
374	    }
375	
376	    fn store(&mut self) -> Result<&Store> {
377	        self.ensure_store()?;
378	        Ok(self.store.as_ref().expect("store opened above"))
379	    }
380	
381	    fn ensure_memory(&mut self) -> Result<()> {
382	        if self.memory.is_none() {
383	            let Some(m) = &self.opts.memory else {
384	                bail!("memory is not enabled on this server (start it with --memory)")
385	            };
386	            self.memory = Some(Memory::open(&m.path, m.settings.clone())?);
387	        }
388	        Ok(())
389	    }
390	
391	    /// Open both stores now so startup problems show up in the log.
392	    pub fn warm_up(&mut self) -> Vec<String> {
393	        let mut lines = Vec::new();
394	        if self.data_enabled() {
395	            match self.store().and_then(|s| s.describe(1)) {
396	                Ok(d) => {
397	                    lines.push(format!("index {} ({} records)", self.opts.index.display(), d.record_count))
398	                }
399	                Err(err) => lines.push(format!("no index yet: {err:#}")),
400	            }
401	        }
402	        if self.opts.memory.is_some() {
403	            match self.ensure_memory().and_then(|_| self.memory.as_ref().expect("opened").stats()) {
404	                Ok(s) => lines.push(format!(
405	                    "memory {} ({} current, namespace {})",
406	                    s.path.display(),
407	                    s.current,
408	                    s.namespace
409	                )),
410	                Err(err) => lines.push(format!("memory unavailable: {err:#}")),
411	            }
412	        }
413	        lines
414	    }
415	
416	    pub fn tools(&mut self) -> Value {
417	        let data = self.data_enabled();
418	        let opened = data && self.ensure_store().is_ok();
419	        let store = if opened { self.store.as_ref() } else { None };
420	        let memory = self.opts.memory.as_ref().map(|m| (m.tools, m.settings.namespace.as_str()));
421	        tool_definitions(store, memory, data)
422	    }
423	
424	    pub fn instructions(&mut self) -> String {
425	        let mut parts = Vec::new();
426	        if self.data_enabled() {
427	            parts.push(DATA_INSTRUCTIONS.to_string());
428	            if let Some(summary) = self.store().ok().and_then(dataset_summary) {
429	                parts.push(summary);
430	            }
431	        }
432	        match self.memory_tools() {
433	            Some(MemoryTools::All) => parts.push(MEMORY_INSTRUCTIONS.into()),
434	            Some(MemoryTools::Recall) => parts.push(RECALL_ONLY_INSTRUCTIONS.into()),
435	            None => {}
436	        }
437	        parts.join(" ")
438	    }
439	
440	    /// Run one tool. Text by default; `format: json` for structured output.
441	    pub fn call(&mut self, name: &str, args: &Value) -> Result<String> {
442	        let text = |k: &str| text_arg(args, k);
443	        let int = |k: &str| int_arg(args, k);
444	        let json_out = text("format").as_deref() == Some("json");
445	        let memory_tool = matches!(name, "remember" | "recall" | "forget" | "memory_describe");
446	        if memory_tool {
447	            if self.opts.memory.is_none() {
448	                bail!("memory is not enabled on this server (start it with --memory)");
449	            }
450	            if self.memory_tools() == Some(MemoryTools::Recall) && matches!(name, "remember" | "forget") {
451	                bail!("this server exposes memory read-only (--memory-tools recall)");
452	            }
453	        } else if !self.data_enabled()
454	            && matches!(name, "search" | "resolve_group" | "get" | "describe" | "aggregate")
455	        {
456	            bail!("no data index on this server; it serves memory only");
457	        }
458	
459	        match name {
460	            "search" => {
461	                let scope = match text("scope").as_deref() {
462	                    None => None,
463	                    Some("group") => Some(Scope::Group),
464	                    Some("others") => Some(Scope::Others),
465	                    Some("all") => Some(Scope::All),
466	                    Some(other) => bail!("unknown scope {other:?}"),
467	                };
468	                let sort = match text("sort").as_deref() {
469	                    None | Some("relevance") => Sort::Relevance,
470	                    Some("newest") => Sort::Newest,
471	                    Some(other) => bail!("unknown sort {other:?}"),
472	                };
473	                let filters = where_filters(args)?;
474	                let req = SearchRequest {
475	                    group: text("group"),
476	                    query: text("query").unwrap_or_default(),
477	                    scope,
478	                    filters,
479	                    since: text("since"),
480	                    until: text("until"),
481	                    sort,
482	                    limit: int("limit").unwrap_or(5).clamp(1, 25),
483	                    offset: int("offset").unwrap_or(0),
484	                    fallback: true,
485	                };
486	                let outcome = self.store()?.search(&req)?;
487	                Ok(if json_out { serde_json::to_string(&outcome)? } else { render::search(&outcome) })
488	            }
489	            "resolve_group" => {
490	                let query = text("query").ok_or_else(|| anyhow::anyhow!("`query` is required"))?;
491	                let store = self.store()?;
492	                let found = store.resolve(&query, int("limit").unwrap_or(10).clamp(1, 25))?;
493	                let about = &store.config().about;
494	                Ok(if json_out {
495	                    serde_json::to_string(
496	                        &json!({"query": query, "candidates": found, "ambiguous": found.len() > 1}),
497	                    )?
498	                } else {
499	                    render::resolve(&query, &found, &about.record, &about.group)
500	                })
501	            }
502	            "get" => {
503	                let id = text("id").ok_or_else(|| anyhow::anyhow!("`id` is required"))?;
504	                match self.store()?.get(&id)? {
505	                    Some(doc) => Ok(serde_json::to_string(&doc)?),
506	                    None => bail!("no record with id {id:?}"),
507	                }
508	            }
509	            "describe" => {
510	                let d = self.store()?.describe(8)?;
511	                Ok(if json_out { serde_json::to_string(&d)? } else { render::describe(&d) })
512	            }
513	            "aggregate" => {
514	                let metric = match text("metric") {
515	                    None => Metric::Count,
516	                    Some(m) => Metric::parse(&m).ok_or_else(|| {
517	                        anyhow::anyhow!("unknown metric {m:?}; use count, distinct, sum, avg, min or max")
518	                    })?,
519	                };
520	                let req = AggregateRequest {
521	                    query: text("query").unwrap_or_default(),
522	                    group: text("group"),
523	                    group_contains: text("group_contains"),
524	                    filters: where_filters(args)?,
525	                    numeric: list_arg(args, "numeric"),
526	                    since: text("since"),
527	                    until: text("until"),
528	                    by: text("by"),
529	                    metric,
530	                    field: text("field"),
531	                    limit: int("limit").unwrap_or(20),
532	                };
533	                let outcome = self.store()?.aggregate(&req)?;
534	                Ok(if json_out { serde_json::to_string(&outcome)? } else { render::aggregate(&outcome) })
535	            }
536	            "remember" => {
537	                let req = Remember {
538	                    text: text("text")
539	                        .ok_or_else(|| anyhow::anyhow!("`text` is required: the one thing to remember"))?,
540	                    kind: match text("kind") {
541	                        Some(k) => Some(
542	                            Kind::parse(&k)
543	                                .ok_or_else(|| anyhow::anyhow!("unknown kind {k:?}; use {}", Kind::NAMES))?,
544	                        ),
545	                        None => None,
546	                    },
547	                    subject: text("subject"),
548	                    key: text("key"),
549	                    tags: list_arg(args, "tags"),
550	                    importance: int("importance").map(|i| i.min(255) as u8),
551	                    confidence: args.get("confidence").and_then(Value::as_f64),
552	                    source: text("source"),
553	                    refs: list_arg(args, "refs"),
554	                    pinned: bool_arg(args, "pinned"),
555	                    expires: text("expires"),
556	                    aliases: list_arg(args, "aliases"),
557	                    ns: text("ns"),
558	                };
559	                self.ensure_memory()?;
560	                let out = self.memory.as_mut().expect("opened").remember(&req)?;
561	                Ok(if json_out { serde_json::to_string(&out)? } else { out.render() })
562	            }
563	            "recall" => {
564	                let req = RecallRequest {
565	                    query: text("query").unwrap_or_default(),
566	                    ns: text("ns"),
567	                    subject: text("subject"),
568	                    kinds: kinds_arg(args)?,
569	                    since: text("since"),
570	                    until: text("until"),
571	                    as_of: text("as_of"),
572	                    history: bool_arg(args, "history"),
573	                    budget: int("budget"),
574	                    limit: int("limit"),
575	                    with_records: bool_arg(args, "with_records"),
576	                    briefing: text("query").is_none()
577	                        && text("subject").is_none()
578	                        && args.get("kind").is_none(),
579	                };
580	                if req.with_records && self.data_enabled() {
581	                    let _ = self.ensure_store();
582	                }
583	                self.ensure_memory()?;
584	                let store = self.store.as_ref();
585	                let out = self.memory.as_mut().expect("opened").recall(&req, store)?;
586	                Ok(if json_out { serde_json::to_string(&out)? } else { out.render() })
587	            }
588	            "forget" => {
589	                let f = Forget {
590	                    id: text("id"),
591	                    subject: text("subject"),
592	                    key: text("key"),
593	                    ns: text("ns"),
594	                    reason: text("reason"),
595	                };
596	                self.ensure_memory()?;
597	                let m = self.memory.as_mut().expect("opened").forget(&f)?;
598	                Ok(if json_out {
599	                    serde_json::to_string(&m)?
600	                } else {
601	                    format!("forgot {}\n  {}\n", m.id, m.line(&crate::now_rfc3339(), false))
602	                })
603	            }
604	            "memory_describe" => {
605	                self.ensure_memory()?;
606	                let s = self.memory.as_ref().expect("opened").stats()?;
607	                Ok(if json_out { serde_json::to_string(&s)? } else { render::memory_stats(&s) })
608	            }
609	            other => bail!("unknown tool {other:?}"),
610	        }
611	    }
612	
613	    /// One JSON-RPC message in, at most one reply out (none for notifications).
614	    pub fn handle(&mut self, msg: &Value) -> Option<Value> {
615	        let id = msg.get("id").cloned();
616	        let method = msg.get("method").and_then(Value::as_str)?;
617	        let params = msg.get("params").cloned().unwrap_or(Value::Null);
618	        let result: Result<Value, (i64, String)> = match method {
619	            "initialize" => {
620	                let asked = params.get("protocolVersion").and_then(Value::as_str).unwrap_or_default();
621	                let version =
622	                    PROTOCOL_VERSIONS.iter().find(|v| **v == asked).unwrap_or(&PROTOCOL_VERSIONS[0]);
623	                Ok(json!({
624	                    "protocolVersion": version,
625	                    "capabilities": {"tools": {"listChanged": false}},
626	                    "serverInfo": {"name": "leviathan", "title": "Leviathan", "version": env!("CARGO_PKG_VERSION")},
627	                    "instructions": self.instructions()
628	                }))
629	            }
630	            "ping" => Ok(json!({})),
631	            "tools/list" => Ok(json!({"tools": self.tools()})),
632	            "resources/list" => Ok(json!({"resources": []})),
633	            "resources/templates/list" => Ok(json!({"resourceTemplates": []})),
634	            "prompts/list" => Ok(json!({"prompts": []})),
635	            "tools/call" => {
636	                let name = params.get("name").and_then(Value::as_str).unwrap_or_default().to_string();
637	                let args = params.get("arguments").cloned().unwrap_or_else(|| json!({}));
638	                Ok(match self.call(&name, &args) {
639	                    Ok(text) => json!({"content": [{"type": "text", "text": text}], "isError": false}),
640	                    Err(err) => {
641	                        json!({"content": [{"type": "text", "text": format!("error: {err:#}")}], "isError": true})
642	                    }
643	                })
644	            }
645	            _ if id.is_none() => return None,
646	            other => Err((-32601, format!("method not found: {other}"))),
647	        };
648	        let id = id?;
649	        Some(match result {
650	            Ok(result) => json!({"jsonrpc": "2.0", "id": id, "result": result}),
651	            Err((code, message)) => {
652	                json!({"jsonrpc": "2.0", "id": id, "error": {"code": code, "message": message}})
653	            }
654	        })
655	    }
656	
657	    /// A raw request body: one message or a batch. `None` when nothing needs
658	    /// a reply (notifications only).
659	    pub fn handle_body(&mut self, body: &str) -> Option<Value> {
660	        match serde_json::from_str::<Value>(body) {
661	            Ok(Value::Array(batch)) => {
662	                let replies: Vec<Value> = batch.iter().filter_map(|m| self.handle(m)).collect();
663	                (!replies.is_empty()).then_some(Value::Array(replies))
664	            }
665	            Ok(msg) => self.handle(&msg),
666	            Err(err) => Some(
667	                json!({"jsonrpc": "2.0", "id": null, "error": {"code": -32700, "message": format!("parse error: {err}")}}),
668	            ),
669	        }
670	    }
671	}
672	
673	fn scalar(v: &Value) -> Option<String> {
674	    match v {
675	        Value::String(s) => Some(s.clone()),
676	        Value::Number(n) => Some(n.to_string()),
677	        Value::Bool(b) => Some(b.to_string()),
678	        _ => None,
679	    }
680	}
681	
682	pub fn serve(opts: ServerOptions) -> Result<()> {
683	    let mut session = Session::new(opts);
684	    for line in session.warm_up() {
685	        eprintln!("[leviathan] mcp {line}");
686	    }
687	    let stdin = io::stdin();
688	    let mut stdout = io::stdout().lock();
689	    for line in stdin.lock().lines() {
690	        let line = line?;
691	        if line.trim().is_empty() {
692	            continue;
693	        }
694	        if let Some(reply) = session.handle_body(&line) {
695	            serde_json::to_writer(&mut stdout, &reply)?;
696	            stdout.write_all(b"\n")?;
697	            stdout.flush()?;
698	        }
699	    }
700	    Ok(())
701	}
702

